// Auto-generated for the Unit Board — AWL Sublist 6
window.A6_DASHBOARD_UNITS = [{"unit":1,"theme":"abstract – be attached to","cards":[{"w":"abstract","p":"adj.","d":"based on ideas, not real things","c":"抽象的","s":"The concept is quite abstract, making it hard for some people to grasp.","t":"這個概念非常抽象，使得一些人很難理解。"},{"w":"abstract of a thesis","p":"n.","d":"a short summary of a research paper","c":"論文摘要","s":"The abstract of a thesis should summarize the key points and findings of the research.","t":"論文摘要應總結研究的主要要點和發現。"},{"w":"accurate","p":"adj.","d":"correct and exact","c":"準確的","s":"The measurements need to be accurate to ensure the experiment's success.","t":"測量需要準確以確保實驗的成功。"},{"w":"inaccurate","p":"adj.","d":"not correct","c":"不準確的","s":"The inaccurate information led to a lot of confusion among the team.","t":"不準確的信息導致團隊中出現了很多混淆。"},{"w":"accurately","p":"adv.","d":"in a correct and exact way","c":"準確地","s":"He accurately predicted the outcome of the election.","t":"他準確地預測了選舉的結果。"},{"w":"accuracy","p":"n.","d":"the quality of being correct","c":"準確度","s":"The accuracy of the data is crucial for making informed decisions.","t":"數據的準確度對於做出明智的決策至關重要。"},{"w":"knowledge","p":"n.","d":"information and understanding","c":"知識","s":"With the right knowledge, you can overcome any challenge.","t":"擁有正確的知識，你可以克服任何挑戰。"},{"w":"acknowledge","p":"v.","d":"to accept that something is true","c":"承認","s":"It's important to acknowledge one's mistakes and learn from them.","t":"承認自己的錯誤並從中學習是很重要的。"},{"w":"acknowledged","p":"adj.","d":"generally accepted as true or good","c":"承認的","s":"He is an acknowledged expert in his field.","t":"他是他領域中公認的專家。"},{"w":"acknowledgement","p":"n.","d":"the act of accepting that something is true","c":"承認","s":"She showed her acknowledgement of the problem by nodding.","t":"她通過點頭表明了她對問題的承認。"},{"w":"aggregate","p":"v./n.","d":"to collect together; a total amount","c":"聚集 / 總計","s":"The aggregate amount of sales over the quarter was quite impressive.","t":"季度的總銷售額非常令人印象深刻。"},{"w":"aggregation","p":"n.","d":"the act of collecting things together","c":"聚集","s":"The aggregation of data was necessary to see the bigger picture.","t":"數據聚集是必要的，以看到更大的圖景。"},{"w":"allocate","p":"v.","d":"to give something for a special purpose","c":"分配","s":"They decided to allocate more funds to the marketing department.","t":"他們決定分配更多的資金給市場營銷部門。"},{"w":"allocated","p":"adj.","d":"given for a special purpose","c":"分配的","s":"The allocated resources were used wisely.","t":"分配的資源被明智地使用了。"},{"w":"allocation","p":"n.","d":"an amount given for a special purpose","c":"分配","s":"The allocation of tasks among team members was fair and efficient.","t":"在團隊成員之間的任務分配是公平和高效的。"},{"w":"assign","p":"v.","d":"to give someone a job or task","c":"分配","s":"The project manager will assign tasks to each team member based on their expertise and availability.","t":"項目經理將根據每個團隊成員的專業知識和可用性分配任務。"},{"w":"assigned","p":"adj.","d":"given as a job or task","c":"已分配的","s":"The assigned duties were clear to everyone, ensuring a smooth workflow within the department.","t":"分配的職責對每個人來說都很清楚，確保部門內的工作流程順利。"},{"w":"assignment","p":"n.","d":"a piece of work given to someone","c":"任務","s":"The assignment required a deep understanding of the subject matter and collaboration among team members.","t":"任務要求對主題內容有深刻的理解並需要團隊成員之間的合作。"},{"w":"attach ...to","p":"phr.","d":"to fasten or add one thing to another","c":"附上...到","s":"Please attach your resume to the email before sending it to the prospective employer.","t":"在將其發送給潛在雇主之前，請將您的簡歷附加到電子郵件中。"},{"w":"be attached to","p":"phr.","d":"to be fastened to; to love someone a lot","c":"附屬於","s":"She has always attached great importance to maintaining a healthy work-life balance.","t":"她始終非常重視保持健康的工作與生活平衡。"}]},{"unit":2,"theme":"attachment (email) – cooperative","cards":[{"w":"attachment (email)","p":"n.","d":"a file sent with an email","c":"附件","s":"Ensure you check the attachment for the detailed instructions on the project.","t":"確保你檢查附件以獲得有關項目的詳細指南。"},{"w":"attachment (feeling)","p":"n.","d":"a feeling of love for someone or something","c":"感情依戀","s":"His attachment to his childhood home was evident when he decided to buy it and restore it.","t":"當他決定購買並恢復它時，他對童年家園的感情依戀顯而易見。"},{"w":"author","p":"n.","d":"a person who writes a book","c":"作者","s":"The author of this critically acclaimed novel will be visiting our city next month for a book signing event.","t":"這本廣受好評的小說的作者將在下個月訪問我們的城市參加簽書會。"},{"w":"authorize","p":"v.","d":"to give official permission","c":"授權","s":"The board will authorize the new policy once all members agree on the proposed changes.","t":"一旦所有成員同意建議的更改，董事會將授權新政策。"},{"w":"authority","p":"n.","d":"power to control people; an expert","c":"權威","s":"The book is considered an authority on the subject, and many scholars refer to it in their work.","t":"這本書被認為是該主題的權威，許多學者在他們的工作中參考它。"},{"w":"bond","p":"n.","d":"a paper you buy from a government","c":"債券","s":"Investing in government bond is seen as a safe option during economic instability.","t":"在經濟不穩定時，投資政府債券被視為一個安全的選擇。"},{"w":"bond","p":"v.","d":"to form a close relationship","c":"結合","s":"The team bond well during the retreat, which helped improve their collaborative efforts.","t":"在撤退期間，團隊很好地結合在一起，這有助於提高他們的協作努力。"},{"w":"bonding","p":"n.","d":"forming a close relationship","c":"結合","s":"The bonding experience helped them understand each other better.","t":"結合的經驗幫助他們更好地理解了彼此。"},{"w":"brief","p":"v.","d":"to give someone information before a task","c":"簡報","s":"The officer will brief the team on the new security protocols tomorrow morning.","t":"該官員將在明天早上向團隊簡報新的安全協議。"},{"w":"brief","p":"adj.","d":"short","c":"簡短的","s":"Despite its brief length, the essay conveyed a powerful message.","t":"儘管篇幅簡短，但論文傳達了一個強有力的信息。"},{"w":"briefing","p":"n.","d":"a meeting to give information","c":"簡報會","s":"The morning briefing is crucial for understanding the day's agenda.","t":"早晨的簡報會對於理解當天的議程至關重要。"},{"w":"be capable of","p":"phr.","d":"having the ability to do something","c":"有能力的","s":"With the proper training, she will be capable of handling even the most challenging situations.","t":"通過適當的培訓，她將能夠處理甚至是最具挑戰性的情況。"},{"w":"capability","p":"n.","d":"the ability to do something","c":"能力","s":"His capability to solve complex problems quickly impressed his supervisors.","t":"他快速解決複雜問題的能力給他的主管留下了深刻的印象。"},{"w":"cite","p":"v.","d":"to mention words from a book or person","c":"引用","s":"Researchers must cite their sources accurately to maintain the integrity of their work.","t":"研究人員必須準確引用他們的來源，以保持其工作的完整性。"},{"w":"cited","p":"adj.","d":"mentioned or quoted","c":"被引用的","s":"The cited studies provide a solid foundation for the argument.","t":"被引用的研究為論點提供了堅實的基礎。"},{"w":"uncited","p":"adj.","d":"not mentioned as a source","c":"未引用的","s":"The paper contained several uncited claims, which raised concerns about its credibility.","t":"論文中包含了幾個未引用的聲明，這引起了人們對其可信度的擔憂。"},{"w":"citation","p":"n.","d":"a mention of a book or writer","c":"引文","s":"Each citation should correspond to a reference at the end of the paper.","t":"每個引文應對應於論文末尾的參考文獻。"},{"w":"cooperate with","p":"phr.","d":"to work together with someone","c":"與...合作","s":"To complete the project on time, our team must cooperate with the other departments efficiently.","t":"為了按時完成項目，我們的團隊必須高效地與其他部門合作。"},{"w":"cooperation","p":"n.","d":"working together","c":"合作","s":"cooperation between various stakeholders is crucial for the success of the initiative.","t":"各利益相關者之間的合作對於該倡議的成功至關重要。"},{"w":"cooperative","p":"adj.","d":"willing to work together","c":"合作的","s":"The cooperative attitude of all team members contributed to the project's success.","t":"所有團隊成員的合作態度促成了項目的成功。"}]},{"unit":3,"theme":"discriminate against – exceeding","cards":[{"w":"discriminate against","p":"phr.","d":"to treat people unfairly","c":"歧視","s":"Laws are in place to protect individuals who are discriminate against based on race, gender, or age.","t":"法律旨在保護因種族，性別或年齡而受歧視的個人。"},{"w":"discrimination","p":"n.","d":"unfair treatment of people","c":"歧視","s":"The fight against discrimination is a long-term effort that requires the dedication of everyone involved.","t":"反歧視的鬥爭是一項長期努力，需要所有參與者的奉獻。"},{"w":"racial discrimination","p":"n.","d":"unfair treatment because of race","c":"種族歧視","s":"racial discrimination is a serious issue that societies across the globe are working to eradicate.","t":"種族歧視是全球各地的社會正在努力消除的嚴重問題。"},{"w":"display","p":"v.","d":"to show something for people to see","c":"顯示","s":"The museum will display rare artifacts from ancient civilizations for a limited time.","t":"博物館將在有限的時間內展示來自古代文明的珍稀文物。"},{"w":"display","p":"n.","d":"a show of things for people to see","c":"顯示","s":"The display of local artwork attracts many visitors to the community center.","t":"地方藝術的展示吸引了許多訪客前往社區中心。"},{"w":"on display = on exhibit","p":"phr.","d":"being shown for people to see","c":"展出","s":"The rare manuscripts will be on display at the National Library for the next three months.","t":"珍稀手稿將在未來三個月內在國家圖書館展出。"},{"w":"diverse","p":"adj.","d":"having many different kinds","c":"多樣的","s":"The diverse ecosystem of the rainforest is home to thousands of unique species.","t":"熱帶雨林的多樣生態系統是成千上萬種獨特物種的家園。"},{"w":"diversity","p":"n.","d":"a range of different things","c":"多樣性","s":"The company is committed to promoting diversity and inclusion in the workplace.","t":"公司致力於促進工作場所的多樣性和包容性。"},{"w":"biodiversity","p":"n.","d":"the variety of living things in an area","c":"生物多樣性","s":"The biodiversity of this area is threatened by industrial development.","t":"這個地區的生物多樣性受到工業發展的威脅。"},{"w":"domain","p":"n.","d":"an area of knowledge or activity","c":"領域","s":"She has become an expert in her domain, contributing significantly to the field of renewable energy.","t":"她已成為她領域的專家，在可再生能源領域做出了重大貢獻。"},{"w":"edit","p":"v.","d":"to correct and improve writing","c":"編輯","s":"Before publishing, it's essential to edit the manuscript carefully to ensure accuracy and clarity.","t":"在出版之前，必須仔細編輯稿件以確保準確性和清晰度。"},{"w":"edited","p":"adj.","d":"corrected and improved","c":"編輯過的","s":"The edited version of the film includes additional scenes that provide more context to the story.","t":"編輯過的電影版本包括提供更多故事背景的額外場景。"},{"w":"unedited","p":"adj.","d":"not corrected or changed","c":"未編輯的","s":"The unedited footage provides a raw and unfiltered look at the events as they unfolded.","t":"未編輯的鏡頭提供了對事件如何發展的原始和未經篩選的看法。"},{"w":"edition","p":"n.","d":"one printing of a book","c":"版本","s":"The latest edition of the software has several new features that enhance user experience.","t":"軟件的最新版本具有多個增強用戶體驗的新功能。"},{"w":"enhance","p":"v.","d":"to make something better","c":"增強","s":"The new training program is designed to enhance the skills and knowledge of the employees.","t":"新的培訓計劃旨在增強員工的技能和知識。"},{"w":"enhanced","p":"adj.","d":"made better","c":"增強的","s":"The enhanced security measures have significantly reduced the incidence of data breaches.","t":"增強的安全措施顯著減少了數據泄露的發生。"},{"w":"enhancement","p":"n.","d":"an improvement","c":"增強","s":"The enhancement of customer service is a priority for the company to improve client satisfaction.","t":"提高客戶服務是公司提高客戶滿意度的重要目標。"},{"w":"estate","p":"n.","d":"land and buildings someone owns","c":"地產","s":"He inherited a large estate from his parents, which included several properties and acres of land.","t":"他從父母那裡繼承了大片地產，包括幾個房產和大量土地。"},{"w":"exceed","p":"v.","d":"to go over a limit","c":"超過","s":"If expenses exceed revenues, the project may not be financially viable.","t":"如果支出超過收入，該項目可能在財務上不可行。"},{"w":"exceeding","p":"adj.","d":"going over a limit","c":"超過的","s":"The manager was impressed with the exceeding effort the team put into completing the project on time.","t":"經理對團隊為按時完成項目所付出的超常努力印象深刻。"}]},{"unit":4,"theme":"excessive – incorporate","cards":[{"w":"excessive","p":"adj.","d":"too much","c":"過度的","s":"excessive consumption of sugary drinks can lead to health issues.","t":"過度飲用含糖飲料可能會導致健康問題。"},{"w":"expert","p":"n.","d":"a person with special skill or knowledge","c":"專家","s":"The expert was called to testify in court due to her extensive knowledge on digital forensics.","t":"由於她在數字取證方面的廣泛知識，專家被要求在法庭上作證。"},{"w":"expertise","p":"n.","d":"special skill or knowledge","c":"專業知識","s":"His expertise in network security was crucial in preventing a potential data leak.","t":"他在網絡安全方面的專業知識對於防止潛在的數據洩漏至關重要。"},{"w":"explicit","p":"adj.","d":"very clear and direct","c":"明確的","s":"The instructions were explicit and left no room for ambiguity.","t":"指令非常明確，沒有任何歧義。"},{"w":"explicit (censored word)","p":"adj.","d":"showing too much (violence or sex)","c":"遭檢查的字)","s":"The explicit content was removed from the film to adhere to the rating guidelines.","t":"為了遵守評分指南，將遭檢查的內容從電影中刪除。"},{"w":"implicit","p":"adj.","d":"suggested but not said directly","c":"含蓄的","s":"The implicit message in the story encourages readers to be empathetic and understanding.","t":"故事中的含蓄信息鼓勵讀者要有同理心和理解力。"},{"w":"federal","p":"adj.","d":"about the national government","c":"聯邦的","s":"The federal government has launched a new initiative to combat climate change.","t":"聯邦政府已經推出了一項新的倡議來對抗氣候變化。"},{"w":"fee","p":"n.","d":"money paid for a service","c":"費用","s":"The admission fee for the museum is ten dollars for adults and five dollars for children.","t":"博物館的入場費是十美元的成人和五美元的兒童。"},{"w":"flexible","p":"adj.","d":"able to change easily","c":"靈活的","s":"The flexible working hours allow employees to maintain a good work-life balance.","t":"靈活的工作時間使員工能夠保持良好的工作與生活平衡。"},{"w":"flexibility","p":"n.","d":"the ability to change easily","c":"靈活性","s":"flexibility in decision-making can lead to better outcomes in unpredictable situations.","t":"在決策中的靈活性可以在不可預測的情況下帶來更好的結果。"},{"w":"furthermore","p":"adv.","d":"also; in addition","c":"此外","s":"The plan is cost-effective; furthermore, it has the potential to significantly reduce the environmental impact.","t":"該計劃具有成本效益；此外，它有可能顯著減少對環境的影響。"},{"w":"gender","p":"n.","d":"being male or female","c":"性別","s":"The survey collected data on various demographics including age, gender, and educational background.","t":"調查收集了包括年齡、性別和教育背景在內的各種人口統計數據。"},{"w":"ignore","p":"v.","d":"to pay no attention to something","c":"忽略","s":"It's unwise to ignore the advice of experienced professionals when making critical decisions.","t":"在做出關鍵決定時，忽略經驗豐富的專業人士的建議是不明智的。"},{"w":"ignored","p":"adj.","d":"not paid attention to","c":"被忽略的","s":"The ignored warnings from the experts led to severe consequences.","t":"專家們被忽略的警告導致了嚴重的後果。"},{"w":"ignorant","p":"adj.","d":"not knowing things you should know","c":"無知的","s":"Remaining ignorant of the laws can lead to unintended violations and penalties.","t":"對法律保持無知可能會導致無意的違規和處罰。"},{"w":"ignorance","p":"n.","d":"lack of knowledge","c":"無知","s":"ignorance of the historical context may lead to a misinterpretation of the event.","t":"對歷史背景的無知可能會導致對事件的誤解。"},{"w":"incentive","p":"n.","d":"something that makes you want to do something","c":"刺激","s":"The company offers an incentive program to motivate employees to meet their quarterly goals.","t":"公司提供了一個刺激計劃，以激勵員工達到他們的季度目標。"},{"w":"incidence","p":"n.","d":"how often something happens","c":"發生率","s":"The incidence of smoking-related illnesses has decreased significantly over the past decade.","t":"過去十年中，吸煙相關疾病的發生率已經顯著下降。"},{"w":"incident","p":"n.","d":"an event, often a bad one","c":"事件","s":"The incident at the factory prompted a review of safety procedures.","t":"工廠的事件促使人們重新審視了安全程序。"},{"w":"incorporate","p":"v.","d":"to include something as a part","c":"納入","s":"It's important to incorporate feedback from all stakeholders when developing a new product.","t":"在開發新產品時，納入所有利益相關者的反饋非常重要。"}]},{"unit":5,"theme":"incorporated – immigration","cards":[{"w":"incorporated","p":"adj.","d":"included as a part","c":"已納入的","s":"The newly incorporated features make the software more user-friendly.","t":"新納入的功能使軟件更加用戶友好。"},{"w":"incorporation","p":"n.","d":"including something as a part","c":"納入","s":"The incorporation of the subsidiary into the larger corporation will take place next month.","t":"子公司將在下個月納入大公司。"},{"w":"index","p":"n.","d":"a list at the back of a book","c":"索引","s":"The book includes an index at the back for easy reference to key topics.","t":"該書在封底包括一個索引，以便輕鬆參考主要主題。"},{"w":"inhibit","p":"v.","d":"to stop or slow something down","c":"抑制","s":"Lack of resources can inhibit the progress of the research project.","t":"資源不足可能抑制研究項目的進展。"},{"w":"inhibition","p":"n.","d":"a feeling that stops you acting freely","c":"抑制","s":"His lack of inhibition allowed him to speak freely in front of the audience.","t":"他缺乏抑制，使他能夠在觀眾面前自由地講話。"},{"w":"initial","p":"adj.","d":"first; at the beginning","c":"初步的","s":"The initial results of the experiment are promising, but further testing is needed.","t":"實驗的初步結果很有希望，但是需要進一步的測試。"},{"w":"initiative","p":"n.","d":"the ability to act first without being told","c":"主動性","s":"Taking initiative to solve problems is valued in this company.","t":"這家公司重視主動解決問題。"},{"w":"input","p":"n.","d":"information or ideas you give","c":"輸入","s":"Your input is crucial for the success of the project.","t":"你的輸入對項目的成功至關重要。"},{"w":"instruct","p":"v.","d":"to tell someone what to do","c":"指示","s":"The teacher will instruct the students on how to complete the assignment.","t":"老師將指示學生如何完成作業。"},{"w":"instructor","p":"n.","d":"a teacher or trainer","c":"指導者","s":"The instructor provided valuable feedback on my performance.","t":"指導者對我的表現提供了寶貴的反饋。"},{"w":"instruction","p":"n.","d":"information on how to do something","c":"指示","s":"Follow the instruction carefully to ensure the task is completed accurately.","t":"仔細遵循指示以確保任務準確完成。"},{"w":"intelligence","p":"n.","d":"the ability to learn and understand","c":"智力","s":"His intelligence and quick thinking were crucial in resolving the crisis.","t":"他的智力和快速思考在解決危機中至關重要。"},{"w":"intelligent","p":"adj.","d":"smart; good at learning","c":"聰明的","s":"She is an intelligent young woman with a bright future ahead of her.","t":"她是一位有前途的聰明年輕女性。"},{"w":"interval","p":"n.","d":"the time between two events","c":"間隔","s":"The training sessions are scheduled at regular interval throughout the week.","t":"整個星期的培訓課程都安排在固定的間隔中。"},{"w":"lecture","p":"n.","d":"a talk given to teach people","c":"講座","s":"The professor will deliver a lecture on modern art at the university auditorium.","t":"教授將在大學禮堂上講授現代藝術的講座。"},{"w":"lecture","p":"v.","d":"to talk angrily to someone about their mistakes","c":"訓斥","s":"It's not helpful to lecture someone for making a mistake; instead, provide constructive feedback.","t":"訓斥某人犯錯是沒有幫助的；相反，應提供建設性的反饋。"},{"w":"migrate","p":"v.","d":"to move from one place to another","c":"遷移","s":"Many birds migrate south for the winter to find warmer climates.","t":"許多鳥類冬天會向南遷移以尋找更暖和的氣候。"},{"w":"migration","p":"n.","d":"moving from one place to another","c":"遷移","s":"The annual migration of wildebeests in Africa is a spectacular natural event.","t":"非洲角馬的年度遷移是壯觀的自然事件。"},{"w":"immigrant","p":"n.","d":"a person who comes to live in another country","c":"移民","s":"The immigrant community contributes significantly to the cultural diversity of the city.","t":"移民社區對城市的文化多樣性做出了重大貢獻。"},{"w":"immigration","p":"n.","d":"coming to live in another country","c":"移民","s":"The country's immigration policy has been a topic of debate among politicians.","t":"該國的移民政策一直是政治家們討論的話題。"}]},{"unit":6,"theme":"minimum – reveal","cards":[{"w":"minimum","p":"adj.","d":"the smallest amount possible","c":"最低的","s":"The minimum requirement for application to this program is a bachelor's degree.","t":"申請該計劃的最低要求是學士學位。"},{"w":"ministry","p":"n.","d":"a government department","c":"部","s":"The ministry of Health has issued new guidelines to combat the spread of the virus.","t":"衛生部發布了新的指南以對抗病毒的傳播。"},{"w":"maximum","p":"adj.","d":"the largest amount possible","c":"最大的","s":"The maximum capacity of the hall is 200 people, so we need to limit the number of attendees.","t":"大廳的最大容量是200人，所以我們需要限制參與者的人數。"},{"w":"motivate","p":"v.","d":"to make someone want to do something","c":"激勵","s":"The promise of a bonus did much to motivate the employees to reach their sales targets.","t":"獎金的承諾在很大程度上激勵了員工達到他們的銷售目標。"},{"w":"motivation","p":"n.","d":"the reason you want to do something","c":"動機","s":"His motivation for learning languages is to communicate with people from different cultures.","t":"他學習語言的動機是與來自不同文化的人交流。"},{"w":"neutral","p":"adj.","d":"not supporting either side","c":"中立的","s":"The mediator remained neutral during the negotiations between the two parties.","t":"調解人在雙方談判期間保持中立。"},{"w":"nevertheless","p":"adv.","d":"but still; however","c":"然而","s":"The hike was challenging; nevertheless, everyone enjoyed the stunning views at the summit.","t":"徒步旅行很具挑戰性；然而，每個人都喜歡山頂上令人驚嘆的景色。"},{"w":"oversea","p":"adj.","d":"in a foreign country","c":"海外的","s":"The company has several oversea branches that contribute to its global presence.","t":"公司有幾個海外分支，有助於其全球影響力。"},{"w":"overseas","p":"adv.","d":"to or in a foreign country","c":"在海外","s":"She will be traveling overseas for business over the next few months.","t":"她將在接下來的幾個月裡出國出差。"},{"w":"precede","p":"v.","d":"to come before something","c":"在...之前","s":"The meeting will precede the workshop, to provide an overview of the topics to be discussed.","t":"會議將在研討會之前舉行，以提供要討論的主題概述。"},{"w":"preceding","p":"adj.","d":"coming just before","c":"在...之前的","s":"The preceding chapters provide the necessary background for understanding the complex theories.","t":"在...之前的章節為理解複雜的理論提供了必要的背景。"},{"w":"presume","p":"v.","d":"to think something is true","c":"假設","s":"We presume that all attendees have a basic understanding of the subject matter.","t":"我們假設所有與會者都對主題有基本的了解。"},{"w":"presumption","p":"n.","d":"something thought to be true","c":"假設","s":"There's a presumption of innocence until proven guilty in the legal system.","t":"在法律系統中，被告在被證明有罪之前被假定為無辜。"},{"w":"ration","p":"n.","d":"a fixed amount of food allowed","c":"定量","s":"Due to the food shortage, each family received a ration of basic supplies.","t":"由於食品短缺，每個家庭都收到了基本供應品的定量。"},{"w":"rational","p":"adj.","d":"based on reason, not feelings","c":"理性的","s":"It's important to make a rational decision based on facts rather than emotions.","t":"基於事實而不是情感做出理性決定是很重要的。"},{"w":"rationality","p":"n.","d":"the ability to think clearly","c":"理性","s":"The debate required a level of rationality to discuss the issues objectively.","t":"辯論需要一定程度的理性以客觀討論問題。"},{"w":"recover","p":"v.","d":"to get well again; to get something back","c":"恢復","s":"The economy has begun to recover after the recent downturn.","t":"經濟在最近的低迷之後已經開始恢復。"},{"w":"recovered","p":"adj.","d":"made well again","c":"恢復的","s":"The recovered artifacts are now on display at the local museum.","t":"恢復的文物現在在當地博物館展出。"},{"w":"recovery","p":"n.","d":"getting well again","c":"恢復","s":"The patient made a full recovery after the surgery.","t":"病人在手術後完全恢復了。"},{"w":"reveal","p":"v.","d":"to show something hidden","c":"揭示","s":"The investigation will reveal the truth behind the incident.","t":"調查將揭示事件背後的真相。"}]},{"unit":7,"theme":"revealed – utility bill","cards":[{"w":"revealed","p":"adj.","d":"shown after being hidden","c":"揭示的","s":"The revealed information shed light on the motives of the individuals involved.","t":"揭示的信息揭示了涉及個人的動機。"},{"w":"revelation","p":"n.","d":"a surprising fact made known","c":"揭示","s":"The revelation that the CEO had been misappropriating funds was shocking to everyone in the company.","t":"CEO一直在挪用資金的揭示讓公司裡的每個人都感到震驚。"},{"w":"scope","p":"n.","d":"the range of a subject or activity","c":"範圍","s":"The scope of the project has expanded to include more communities.","t":"該項目的範圍已擴大到包括更多社區。"},{"w":"subsidiary","p":"n.","d":"a company owned by a larger company","c":"子公司","s":"The parent company has several subsidiary in different regions.","t":"父公司在不同地區有幾家子公司。"},{"w":"tape","p":"n.","d":"a sticky strip used to fasten things","c":"膠帶","s":"She used a strong adhesive tape to fix the broken handle.","t":"她用強力黏合膠帶修理了斷掉的把手。"},{"w":"trace","p":"n.","d":"a small sign that something was there","c":"痕迹","s":"Archaeologists found trace of ancient civilizations at the site.","t":"考古學家在該地點找到了古文明的痕迹。"},{"w":"trace","p":"v.","d":"to find the origin of something","c":"追溯","s":"It's difficult to trace the origins of the legend.","t":"追溯傳說的起源很困難。"},{"w":"transform","p":"v.","d":"to change completely","c":"轉變","s":"The renovation will transform the old building into a modern workspace.","t":"裝修將把老建築變成現代化的工作空間。"},{"w":"transformation","p":"n.","d":"a complete change","c":"轉變","s":"The transformation of the city's skyline over the decades is remarkable.","t":"數十年來，城市天際線的轉變非常顯著。"},{"w":"transport","p":"n.","d":"a system for moving people or goods","c":"運輸","s":"The city's transport system is well-developed, with numerous buses, trains, and subway lines.","t":"該市的運輸系統非常發達，有許多公共汽車、火車和地鐵線路。"},{"w":"transport","p":"v.","d":"to move people or goods","c":"運輸","s":"They plan to transport the goods by ship to reduce costs.","t":"他們計劃通過船運來減少成本。"},{"w":"transportation","p":"n.","d":"a system for moving people or goods","c":"運輸","s":"Investments in public transportation have significantly improved the connectivity within the city.","t":"在公共運輸方面的投資顯著提高了城市內的連接性。"},{"w":"underlying","p":"adj.","d":"basic but not easy to see","c":"基本的","s":"Understanding the underlying principles is crucial for solving complex problems.","t":"瞭解基本原則對於解決複雜問題至關重要。"},{"w":"utility","p":"n.","d":"a service like water or electricity","c":"公用事業","s":"The utility company is responsible for ensuring a steady supply of electricity and water to the residents.","t":"公用事業公司負責確保向居民提供穩定的電力和水供應。"},{"w":"utility bill","p":"n.","d":"a bill for water, gas or electricity","c":"公用事業賬單","s":"She was shocked by the high utility bill and decided to reduce her energy consumption.","t":"她對高額的公用事業賬單感到震驚，並決定減少她的能源消耗。"}]}];
